const meta = {
  component: Alert,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Displays a callout for agent activity, decisions, and failures. Each variant supplies its own icon.

**Import:** `@/registry/erbium/ui/alert`

## Usage

```tsx
import { Alert, AlertAction, AlertDescription, AlertTitle } from "@/registry/erbium/ui/alert";
```

```tsx
<Alert variant="warning">
  <AlertTitle>Approval required</AlertTitle>
  <AlertDescription>The agent needs permission to install a new dependency.</AlertDescription>
  <AlertAction>
    <Button variant="outline">Review</Button>
  </AlertAction>
</Alert>
```

## Composition

Use the following composition to build an `Alert`:

```text
Alert
├── AlertTitle
├── AlertDescription
└── AlertAction
```",
      },
    },
    layout: "centered",
  },
} satisfies Meta<typeof Alert>;

export default { ...meta, title: "Components/Alert",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof Alert> = {
  argTypes: {
    variant: {
      control: "select",
      options: ["default", "error", "info", "success", "warning"],
    },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { Alert, AlertDescription, AlertTitle } from "@/registry/erbium/ui/alert";
import type * as React from "react";
import { alertContent } from "../helpers";

export const defaultProps = {
  className: "",
  variant: "default",
} satisfies React.ComponentProps<typeof Alert>;

export default function AlertPlaygroundExample(
  args: React.ComponentProps<typeof Alert> = defaultProps,
) {
  const content = alertContent[args.variant ?? "default"];

  return (
    <Alert {...args} className={`w-96 ${args.className ?? ""}`}>
      <AlertTitle>{content.title}</AlertTitle>
      <AlertDescription>{content.description}</AlertDescription>
    </Alert>
  );
}
" },
    },
  },
  render: PlaygroundExample,
};

